pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testRegression_property() public {
        c.adjustAdminAccess(address(this), true);
        c.createGameItem("Item", "ipfs://test", false, true, 0, 1 ether, 100);

        bool zeroBalanceReverted = false;
        try c.balanceOf(address(0), 0) {
        } catch {
            zeroBalanceReverted = true;
        }

        assertTrue(zeroBalanceReverted, "Bug: balanceOf should revert for zero address");
    }
}
